use std::io::{Cursor, Read, Write};
use zip::{write::SimpleFileOptions, CompressionMethod, ZipArchive, ZipWriter, AesMode};
use zip::unstable::stream::{ZipStreamReader, ZipStreamVisitor, ZipStreamFileMetadata};
use zip::unstable::write::FileOptionsExt;

fn stored() -> SimpleFileOptions { SimpleFileOptions::default().compression_method(CompressionMethod::Stored) }
fn archive(options: SimpleFileOptions) -> Cursor<Vec<u8>> {
    let mut w = ZipWriter::new(Cursor::new(Vec::new()));
    w.start_file("a", options).unwrap();
    w.write_all(b"hello").unwrap();
    w.finish().unwrap()
}

#[test]
fn finish_readable_zip64_preserves_sizes_and_contents() {
    let mut w = ZipWriter::new(Cursor::new(Vec::new()));
    w.start_file("a", stored().large_file(true)).unwrap();
    w.write_all(b"hello").unwrap();
    let mut a = w.finish_into_readable().unwrap();
    let mut reopened = ZipArchive::new(a.clone().into_inner()).unwrap();
    assert_eq!(reopened.by_name("a").unwrap().size(), 5);
    let mut f = a.by_name("a").unwrap();
    assert_eq!(f.size(), 5);
    let mut s = Vec::new();
    f.read_to_end(&mut s).unwrap();
    assert_eq!(s, b"hello");
}

#[test]
fn raw_copy_zipcrypto_preserves_encryption() {
    let mut a = ZipArchive::new(archive(stored().with_deprecated_encryption(b"password"))).unwrap();
    let mut w = ZipWriter::new(Cursor::new(Vec::new()));
    w.raw_copy_file(a.by_index_raw(0).unwrap()).unwrap();
    let mut copied = ZipArchive::new(w.finish().unwrap()).unwrap();
    assert!(copied.by_index_raw(0).unwrap().encrypted());
    let mut s = Vec::new();
    copied.by_index_decrypt(0, b"password").unwrap().read_to_end(&mut s).unwrap();
    assert_eq!(s, b"hello");
}

#[test]
fn raw_copy_preserves_symlink_type() {
    let mut w = ZipWriter::new(Cursor::new(Vec::new()));
    w.add_symlink("a", "target", stored()).unwrap();
    let mut a = ZipArchive::new(w.finish().unwrap()).unwrap();
    assert!(a.by_index(0).unwrap().is_symlink());
    let mut w = ZipWriter::new(Cursor::new(Vec::new()));
    w.raw_copy_file(a.by_index(0).unwrap()).unwrap();
    let mut a = ZipArchive::new(w.finish().unwrap()).unwrap();
    assert!(a.by_index(0).unwrap().is_symlink());
}

#[test]
fn stream_writer_aes_roundtrip() {
    let mut w = ZipWriter::new_stream(Vec::new());
    w.start_file("a", stored().with_aes_encryption(AesMode::Aes128, "password")).unwrap();
    w.write_all(b"hello").unwrap();
    let bytes = w.finish().unwrap().into_inner();
    let mut a = ZipArchive::new(Cursor::new(bytes)).unwrap();
    let mut s = Vec::new();
    a.by_index_decrypt(0, b"password").unwrap().read_to_end(&mut s).unwrap();
    assert_eq!(s, b"hello");
}

#[test]
fn stream_writer_zip64_roundtrip() {
    let mut w = ZipWriter::new_stream(Vec::new());
    w.start_file("a", stored().large_file(true)).unwrap();
    w.write_all(b"hello").unwrap();
    let bytes = w.finish().unwrap().into_inner();
    let mut a = ZipArchive::new(Cursor::new(bytes)).unwrap();
    assert_eq!(a.by_index(0).unwrap().size(), 5);
}

#[derive(Default)]
struct Visitor { files: usize, metadata: usize }
impl ZipStreamVisitor for Visitor {
    fn visit_file<R: Read>(&mut self, f: &mut zip::read::ZipFile<'_, R>) -> zip::result::ZipResult<()> {
        let mut s = Vec::new();
        f.read_to_end(&mut s)?;
        assert_eq!(s, b"hello");
        self.files += 1;
        Ok(())
    }
    fn visit_additional_metadata(&mut self, _: &ZipStreamFileMetadata) -> zip::result::ZipResult<()> {
        self.metadata += 1;
        Ok(())
    }
}
#[test]
fn stream_reader_delivers_central_metadata() {
    let mut v = Visitor::default();
    ZipStreamReader::new(archive(stored()).into_inner().as_slice()).visit(&mut v).unwrap();
    assert_eq!(v.files, 1);
    assert_eq!(v.metadata, 1);
}
#[test]
fn stream_reader_empty_archive() {
    let bytes = ZipWriter::new(Cursor::new(Vec::new())).finish().unwrap().into_inner();
    ZipStreamReader::new(bytes.as_slice()).visit(&mut Visitor::default()).unwrap();
}
#[test]
fn streamed_file_data_start_is_documented_zero() {
    let bytes = archive(stored()).into_inner();
    let mut input = bytes.as_slice();
    let file = zip::read::read_zipfile_from_stream(&mut input).unwrap().unwrap();
    assert_eq!(file.data_start(), 0);
}
#[test]
fn long_filename_returns_error_without_panic() {
    let mut w = ZipWriter::new(Cursor::new(Vec::new()));
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| w.start_file("x".repeat(65536), stored())));
    if result.is_err() { std::mem::forget(w); }
    assert!(result.is_ok(), "start_file panicked");
    assert!(result.unwrap().is_err());
}
#[test]
fn symlink_from_path_preserves_relative_target() {
    let mut w = ZipWriter::new(Cursor::new(Vec::new()));
    w.add_symlink_from_path("dir/link", "../target", stored()).unwrap();
    let mut a = ZipArchive::new(w.finish().unwrap()).unwrap();
    let mut s = String::new();
    a.by_name("dir/link").unwrap().read_to_string(&mut s).unwrap();
    assert_eq!(s, "../target");
}
#[test]
fn deep_copy_after_stream_read_state_roundtrip() {
    let mut w = ZipWriter::new(Cursor::new(Vec::new()));
    w.start_file("a", stored()).unwrap();
    w.write_all(b"hello").unwrap();
    w.deep_copy_file("a", "b").unwrap();
    let mut a = ZipArchive::new(w.finish().unwrap()).unwrap();
    let mut s = String::new();
    a.by_name("b").unwrap().read_to_string(&mut s).unwrap();
    assert_eq!(s, "hello");
}
